def get_canonical_frames(suite: str) -> List[np.ndarray]:
    suite_list = RAW_PROTOTYPES.get(suite, [])
    frames = []
    for b64_str in suite_list:
        raw = zlib.decompress(base64.b64decode(b64_str))
        frames.append(np.frombuffer(raw, dtype=np.uint8).reshape((60, 64)))
    return frames

def get_canonical_frame(suite: str, idx: int = 0) -> Optional[np.ndarray]:
    frames = get_canonical_frames(suite)
    if not frames:
        return None
    if 0 <= idx < len(frames):
        return frames[idx]
    return frames[0]
